/**
 * A round mark identifying a person or workspace (`design/components/avatar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/avatar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import {
  Icon,
  avatarTone,
  claimSlot,
  createCell,
  createDerived,
  initialsOf,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/avatar.module.css'

export type AvatarSize = NonNullable<AvatarProps['size']>

export interface AvatarProps {
  /**
   * Set only when the avatar stands alone; beside a visible name it would repeat the name, so it
   * is `aria-hidden` instead.
   */
  label?: string
  /**
   * Initials come from this. "Ada Lovelace" → AL; one word → its first two.
   */
  name: string
  size?: 'sm' | 'md' | 'lg'
  src?: string
}

/** A round mark identifying a person or workspace. */
export default function Avatar(given: AvatarProps): JSX.Element {
  const props = mergeProps({ size: 'md' } as Defaults<AvatarProps, 'size'>, claimSlot(given))
  return scope(() => {
    const failed = createCell('')
    const initials = createDerived(() => initialsOf(props.name))
    const showImage = createDerived(() => props.src !== undefined && failed.value !== props.src)
    const fallback = createDerived(() => (initials.value === '' ? 'icon' : 'initials'))
    const named = createDerived(() => props.label !== undefined)
    return (
      <span
        class={styles.avatar}
        data-size={props.size}
        data-fallback={showImage.value ? undefined : fallback.value}
        data-tone={
          fallback.value === 'initials' && !showImage.value ? avatarTone(props.name) : undefined
        }
        role={named.value ? 'img' : undefined}
        aria-label={props.label}
        aria-hidden={!named.value ? true : undefined}
        data-member="avatar"
      >
        {showImage.value ? (
          <img
            class={styles.image}
            src={props.src}
            alt={''}
            draggable="false"
            onerror={() => (failed.value = props.src ?? '')}
          />
        ) : null}
        {fallback.value === 'icon' ? (
          <Icon name="user" size={props.size} />
        ) : (
          <span class={styles.initials}>{initials.value}</span>
        )}
      </span>
    )
  })
}
